 /* ---------- History: the Mughal empire, Sir Syed Ahmad Khan, Fatima Jinnah, Ancient Persia, explorers and maps ---------- */
 paper("g3-history",[
  pg("History Practice Paper (1)","","Practise the Mughal empire for the term 2 test.",
   CH("1. Circle the right answer. (4 marks)",[["The first Mughal emperor was ...",["Babur","Akbar"],0],["Babur won the Battle of Panipat in ...",["1947","1526"],1],["The Taj Mahal was built by ...",["Shah Jahan","Aurangzeb"],0],["The Mughals ruled for over ... years.",["30","300"],1]]),
   F("2. Number the emperors in order, 1 to 4. (4 marks)",["Akbar {{2}}","Aurangzeb {{4}}","Babur {{1}}","Shah Jahan {{3}}"],2),
   CH("3. True or false? Circle. (5 marks)",[["Mughal gardens had fountains and water channels.",0],["Babur came from Central Asia.",0],["The Mughals ruled only for ten years.",1],["Shah Jahan built the Taj Mahal in memory of his wife.",0],["The Mughal empire never reached the land that is Pakistan today.",1]],TF)),
  pg("History Practice Paper (2)","Lahore has many Mughal buildings.","Practise Mughal buildings and Sir Syed Ahmad Khan.",
   CN(["castle","national-park"],"In Lahore you can visit the Lahore Fort, the Shalimar Gardens built by Shah Jahan, and the Badshahi Mosque built by Aurangzeb.","Mughal Lahore"),
   MA("4. Match the place or event to the emperor. Write the letter in the box. (3 marks)",["Shalimar Gardens","Badshahi Mosque","Battle of Panipat"],["Shah Jahan","Aurangzeb","Babur"]),
   CH("5. Sir Syed Ahmad Khan. Circle. (4 marks)",[["He was born in ...",["Karachi","Delhi"],1],["He believed the key to a better future was ...",["education","war"],0],["In 1875 he opened a school at ...",["Lahore","Aligarh"],1],["His magazine was called ...",["Tahzib-ul-Akhlaq","the Rihla"],0]]),
   WP("6. Timeline maths. (3 marks)",["Babur won at Panipat in 1526. That was {{500}} years before 2026.","Sir Syed was born in 1817 and died in 1898. He lived for {{81}} years.","The Aligarh school opened in 1875 and became a university in 1920. That is {{45}} years later."])),
  pg("History Practice Paper (3)","Sir Syed wanted Muslims to learn modern subjects.","Practise Sir Syed's work for education.",
   CN(["school","graduation-cap"],"Sir Syed set up the Scientific Society to translate English books on science and history into Urdu. His school at Aligarh taught science, maths and English as well as Urdu, Persian and Arabic.","Education for all"),
   BK(["1864","English","Urdu","England"]),
   F("7. Fill in. (4 marks)",["He set up the Scientific Society in {{1864}}.","It translated {{English}} books into {{Urdu}}.","In 1869 he visited {{England}}."],1),
   CH("8. True or false? Circle. (3 marks)",[["Students at Aligarh learnt science and English.",0],["Sir Syed did not care about schools.",1],["In 1920 the college became Aligarh Muslim University.",0]],TF),
   WR("9. Why do you think Sir Syed wanted Muslims to learn science and English? (2 marks)",[L,L])),
  pg("History Practice Paper (4)","Fatima Jinnah is the Mother of the Nation.","Practise the life and work of Fatima Jinnah.",
   CH("10. Circle the right answer. (4 marks)",[["Fatima Jinnah was the ... of Quaid-e-Azam.",["younger sister","daughter"],0],["She was born in ...",["Lahore","Karachi"],1],["The people of Pakistan call her ...",["Madar-e-Millat","Shaheen"],0],["Madar-e-Millat means ...",["Daughter of the East","Mother of the Nation"],1]]),
   BK(["dentist","1929","women"]),
   F("11. Fill in. (3 marks)",["She trained as a {{dentist}}.","In {{1929}} she moved in with her brother.","She encouraged Muslim {{women}} to join the Pakistan Movement."],1),
   CH("12. What does it show about her? Circle. (2 marks)",[["She travelled with her brother for almost twenty years.",["loyalty","laziness"],0],["She helped refugees in 1947.",["greed","kindness"],1]]),
   WP("13. Timeline maths. (1 mark)",["She was born in 1893. In 1947 she was {{54}} years old."])),
  pg("History Practice Paper (5)","Ancient Persia was one of the biggest empires the world had seen.","Practise Ancient Persia and how it was ruled.",
   CN(["world-map","crown"],"About 2,500 years ago Persian kings ruled from Egypt and Turkey in the west to the River Indus in the east. Darius the Great built Persepolis.","Ancient Persia"),
   CH("14. Circle the right answer. (5 marks)",[["Ancient Persia was in the land that is now ...",["Iran","Egypt"],0],["The first great Persian king was ...",["Akbar","Cyrus"],1],["It stretched east as far as the River ...",["Nile","Indus"],1],["Darius built the palace city of ...",["Persepolis","Harappa"],0],["Persian gold coins were called ...",["rupees","darics"],1]]),
   MA("15. Match the word to its meaning. Write the letter in the box. (5 marks)",["satrap","satrapy","Royal Road","the King's Eyes and Ears","daric"],["a governor","a province of the empire","a long road with rest stations","inspectors who checked the governors","a Persian gold coin"])),
  pg("History Practice Paper (6)","BCE years count down towards year 1.","Practise BCE dates and how Persia kept in touch.",
   WP("16. Timeline maths. (3 marks)",["Cyrus began to build the empire about 550 BCE. Alexander took it in 330 BCE. That is {{220}} years later.","Which came first, 550 BCE or 330 BCE? {{550 BCE}}","Relay riders crossed 2,700 km of the Royal Road in 9 days. They rode {{300}} km each day."]),
   CH("17. True or false? Circle. (4 marks)",[["Riders on fresh horses carried messages like a relay race.",0],["Darius split the empire into satrapies.",0],["The ruins of Persepolis can still be seen in Iran.",0],["Persia had no roads at all.",1]],TF),
   WR("18. Why did the Persian empire need the Royal Road? (2 marks)",[L,L]),
   CH("19. Circle the right answer. (1 mark)",[["Darius made taxes ...",["fair","secret"],0]])),
  pg("History Practice Paper (7)","Explorers travelled to learn about new places.","Practise famous explorers and mapmakers.",
   MA("20. Match the explorer to what they did. Write the letter in the box. (5 marks)",["Ibn Battuta","Al-Idrisi","Marco Polo","Zheng He","Vasco da Gama"],["travelled for 29 years and wrote the Rihla","made a world map in 1154","went from Venice in Italy to China","a Chinese admiral who led huge treasure ships","sailed around Africa to India"]),
   BK(["Morocco","Rihla","south"]),
   F("21. Fill in. (3 marks)",["Ibn Battuta was born in {{Morocco}}.","His travels were written in a book called the {{Rihla}}.","On Al-Idrisi's map, {{south}} was at the top."],1),
   CH("22. True or false? Circle. (2 marks)",[["Most places explorers reached already had people living there.",0],["Long ago, explorers travelled by plane.",1]],TF)),
  pg("History Practice Paper (8)","Explorers needed tools to find their way.","Practise explorers' tools and old and new maps.",
   BK(["compass","sails","anchor","hourglass"]),
   FP("23. Write the tool. (4 marks)",[["compass","A {{compass}} needle points north."],["sailboat","Wind fills the {{sails}}."],["anchor","An {{anchor}} keeps a ship still."],["hourglass-done","An {{hourglass}} measures time."]],2),
   CH("24. Old map or new map? Circle. (4 marks)",[["has pictures of sea monsters",0],["made from satellite photos",1],["has blank spaces for unknown lands",0],["shows where you are with a blue dot",1]],["old map","new map"]),
   WP("25. Timeline maths. (2 marks)",["Ibn Battuta travelled from 1325 to 1354. That is {{29}} years.","Al-Idrisi made his map in 1154. Vasco da Gama reached India in 1498. That is {{344}} years later."])),
  pg("History Practice Paper (9)","Put the term's history in order.","Practise a timeline of the term 2 topics.",
   F("26. Number the events in order, 1 to 5 (oldest first). (5 marks)",["Sir Syed opens his school at Aligarh. {{4}}","Darius builds Persepolis. {{1}}","Fatima Jinnah helps refugees in Pakistan. {{5}}","Al-Idrisi makes his world map. {{2}}","Babur wins the Battle of Panipat. {{3}}"],1),
   CH("27. Who am I? Circle. (5 marks)",[["I won the Battle of Panipat in 1526.",["Babur","Darius"],0],["I built a grand palace city in Persia.",["Darius","Babur"],0],["I started a school at Aligarh.",["Ibn Battuta","Sir Syed"],1],["I looked after the Quaid and his health.",["Fatima Jinnah","Mumtaz Mahal"],0],["I travelled for 29 years.",["Al-Idrisi","Ibn Battuta"],1]]),
   WR("28. Choose one person from this term. Write two reasons they are remembered. (2 marks)",[L,L])),
  pg("History Practice Paper (10)","Think carefully. Add up your marks from all ten pages.","Reason about the Mughals, Sir Syed, Fatima Jinnah, Persia and explorers.",
   CH("29. True or false? Circle. (6 marks)",[["The Badshahi Mosque is in Lahore.",0],["Sir Syed was born in 1947.",1],["Fatima Jinnah was a dentist.",0],["Persepolis is in Pakistan.",1],["Zheng He was a Chinese admiral.",0],["Al-Idrisi made his map in 1154.",0]],TF),
   F("30. Spot the mistake. Write the right word. (3 marks)",["Aurangzeb was the first Mughal emperor. → {{Babur}}","Sir Syed opened his school at Lahore. → {{Aligarh}}","Ibn Battuta came from China. → {{Morocco}}"],1),
   WR("31. Which of this term's people would you most like to meet? Why? (2 marks)",[L,L,L]),
   WR(...HOW))
 ]);

 /* ---------- Geography: climate zones, natural resources, population and cities, pollution, reading atlases ---------- */
 paper("g3-geography",[
  pg("Geography Practice Paper (1)","","Practise climate zones for the term 2 test.",
   CH("1. Weather or climate? Circle. (4 marks)",[["It is raining in Lahore today.",0],["Karachi is usually warm all year.",1],["The Sahara gets very little rain every year.",1],["It is windy this afternoon.",0]],["weather","climate"]),
   CH("2. Circle the right answer. (3 marks)",[["Near the Equator it is ...",["hot","cold"],0],["Near the Poles it is ...",["hot","cold"],1],["The Equator is ...",["a real wall","an imaginary line"],1]]),
   WP("3. January temperatures: Karachi 19 °C, Lahore 13 °C, Quetta 4 °C, Skardu −2 °C. (3 marks)",["Karachi is {{6}} degrees warmer than Lahore.","Lahore is {{9}} degrees warmer than Quetta.","The coldest city is {{Skardu}}."])),
  pg("Geography Practice Paper (2)","Plants and animals are suited to their climate.","Practise climate zones and how living things cope.",
   CN(["desert","cactus"],"A desert gets very little rain. The Thar desert in Sindh and the Sahara in Africa are deserts. A cactus stores water. A camel can go for days without drinking.","Deserts"),
   MA("4. Match the climate zone to its description. Write the letter in the box. (4 marks)",["hot desert","polar","rainforest","mild"],["very dry, hot days, cold nights","freezing cold, ice and snow","hot and wet all year","not too hot and not too cold"]),
   CH("5. Why does it help? Circle. (3 marks)",[["A cactus has thick stems.",["to store water","to catch fish"],0],["A polar bear has thick fur.",["to keep cool","to keep warm"],1],["A camel has wide feet.",["to walk on sand","to swim"],0]]),
   WR("6. Describe the climate where you live. (2 marks)",[L,L])),
  pg("Geography Practice Paper (3)","Natural resources come from nature.","Practise renewable and non-renewable resources.",
   CH("7. Renewable or non-renewable? Circle. (6 marks)",[["sunlight",0],["coal",1],["wind",0],["gas",1],["trees",0],["oil",1]],["renewable","non-renewable"]),
   BK(["Salt","pink","water"]),
   F("8. Fill in. (3 marks)",["The Khewra Salt Mine is in the {{Salt}} Range in Punjab.","Its rock salt is {{pink}}.","Tarbela Dam uses {{water}} to make electricity."],1),
   CH("9. Circle the right answer. (2 marks)",[["Non-renewable resources ...",["will run out","grow back"],0],["Renewable resources ...",["will run out","can be used again and again"],1]])),
  pg("Geography Practice Paper (4)","We use natural resources every day.","Practise how we use and save resources.",
   MA("10. Match the resource to how we use it. Write the letter in the box. (5 marks)",["cotton","water at a dam","gas","soil","wood"],["making cloth","making electricity","cooking food","growing crops","making furniture"]),
   CH("11. Saving or wasting? Circle. (6 marks)",[["walking to a nearby shop instead of driving",0],["leaving the TV on all night",1],["switching off the fan when you leave",0],["leaving the tap running",1],["planting a new tree",0],["throwing away paper with one side used",1]],["saving","wasting"]),
   WR("12. Write two ways your family can save gas or electricity. (2 marks)",[L,L])),
  pg("Geography Practice Paper (5)","Population is the number of people in a place.","Practise population, villages, towns and cities.",
   CN(["busts-in-silhouette","cityscape"],"A census counts all the people in a country. Pakistan's census in 2023 counted more than 240 million people. Moving from villages to cities is called migration.","Population"),
   CH("13. Village, town or city? Circle. (3 marks)",[["millions of people, tall buildings and universities",2],["farms and a few hundred people",0],["shops, schools and a market",1]],["village","town","city"]),
   CH("14. Rural or urban? Circle. (4 marks)",[["a farm with buffaloes",0],["a busy city street",1],["a small mountain village",0],["a shopping centre in Karachi",1]],["rural","urban"]),
   BK(["census","migration","density"]),
   F("15. Fill in. (3 marks)",["Counting all the people is a {{census}}.","Moving from villages to cities is {{migration}}.","How many people live in each square kilometre is population {{density}}."],1)),
  pg("Geography Practice Paper (6)","Some places are crowded and some are empty.","Practise why cities grow and population maths.",
   CH("16. Why do people move to cities? Circle. (4 marks)",[["to find jobs",0],["to go to good schools",0],["to have fewer hospitals",1],["to get electricity",0]],["a reason","not a reason"]),
   WP("17. Population maths. (3 marks)",["A town has 2,000 people on 10 sq km. That is {{200}} people in each sq km.","City A has 500 people in each sq km. City B has 300. City A has {{200}} more.","A village of 600 people grows by 150. Now it has {{750}} people."]),
   CH("18. Crowded or empty? Circle. (3 marks)",[["flat land near a river",0],["high, snowy mountains",1],["a dry desert",1]],["crowded","empty"])),
  pg("Geography Practice Paper (7)","Pollution makes the environment dirty or unsafe.","Practise types of pollution and the Air Quality Index.",
   CH("19. Which kind of pollution? Circle. (4 marks)",[["smoke from factories",0],["plastic in a river",1],["litter in a park",2],["loud horns at night",3]],["air","water","land","noise"]),
   NO("Air Quality Index (AQI): 0 to 50 good, 51 to 100 fair, 101 to 200 unhealthy, over 200 very unhealthy."),
   BK(["good","fair","unhealthy","very unhealthy"]),
   F("20. Read the AQI. (4 marks)",["AQI 30 is {{good}}.","AQI 150 is {{unhealthy}}.","AQI 80 is {{fair}}.","AQI 250 is {{very unhealthy}}."],2),
   CH("21. On a day with AQI 300, what should you do? Circle. (2 marks)",[["",["play outside all day","stay indoors more"],1],["",["wear a mask outside","burn rubbish"],0]])),
  pg("Geography Practice Paper (8)","Reduce, reuse and recycle.","Practise the three Rs and caring for the environment.",
   CN(["recycling-symbol","litter-in-bin-sign"],"Reduce means use less. Reuse means use things again. Recycle means turn old things into new things.","The three Rs"),
   CH("22. Reduce, reuse or recycle? Circle. (8 marks)",[["turning old bottles into new ones",2],["using a jar as a pencil pot",1],["taking a cloth bag to the shop",0],["turning old paper into new paper",2],["giving old clothes to a cousin",1],["switching off lights",0],["mending a torn bag instead of buying a new one",1],["turning old cans into new cans",2]],["reduce","reuse","recycle"]),
   WR("23. Write two ways to make your school less polluted. (2 marks)",[L,L,L])),
  pg("Geography Practice Paper (9)","An atlas is a book of maps.","Practise directions, continents, oceans and atlas skills.",
   CH("24. Look at a map of Pakistan. Circle. (4 marks)",[["Lahore is ... of Karachi.",["north-east","south-west"],0],["Quetta is ... of Lahore.",["north-east","south-west"],1],["Gilgit is ... of Islamabad.",["north","south"],0],["Karachi is ... of Islamabad.",["north-east","south-west"],1]]),
   F("25. Fill in. (5 marks)",["There are {{7}} continents and {{5}} oceans.","Pakistan is in the continent of {{Asia}}.","The ocean south of Pakistan is the {{Indian}} Ocean.","The biggest ocean is the {{Pacific}}."],1),
   MA("26. Match the atlas word to its meaning. Write the letter in the box. (4 marks)",["key","scale","index","compass rose"],["explains the symbols on a map","shows how map distances compare to real ones","an A to Z list of places at the back","shows north, south, east and west"])),
  pg("Geography Practice Paper (10)","Think carefully. Add up your marks from all ten pages.","Reason about climate, resources, population, pollution and atlases.",
   CH("27. True or false? Circle. (6 marks)",[["Climate is the weather on one day.",1],["Karachi is a big port city.",0],["Coal is non-renewable.",0],["Cities are urban places.",0],["AQI 20 means very dirty air.",1],["Between north and east is north-east.",0]],TF),
   F("28. Spot the mistake. Write the right word. (3 marks)",["The Thar desert is in Balochistan. → {{Sindh}}","Wind will run out one day. → wind is {{renewable}}","Antarctica is an ocean. → it is a {{continent}}"],1),
   WR("29. Why do few people live high in the mountains? (2 marks)",[L,L,L]),
   WR(...HOW))
 ]);
